//! Deterministic MLS test-signal generation for acoustic latency measurement.

/// Length of one maximal-length sequence period for the degree-17 LFSR.
pub const MLS_PERIOD: usize = (1 << 17) - 1;

/// Bit mask selecting the 17 LFSR state bits.
const LFSR_STATE_MASK: u32 = (1 << 17) - 1;

/// Returns one full period of a degree-17 maximal-length sequence mapped to
/// `+1.0`/`-1.0`, generated by the primitive polynomial `x^17 + x^3 + 1`.
///
/// A zero `seed` is replaced with `1` because an all-zero LFSR state never
/// advances. The sequence has the MLS autocorrelation property: the zero-lag
/// peak equals the period and every other lag is `-1`.
#[must_use]
pub fn mls_sequence(seed: u32) -> Vec<f32> {
    let mut state = seed & LFSR_STATE_MASK;
    if state == 0 {
        state = 1;
    }
    let mut sequence = Vec::with_capacity(MLS_PERIOD);
    for _ in 0..MLS_PERIOD {
        let head = (state >> 16) & 1;
        let tapped = (state >> 2) & 1;
        let new_bit = head ^ tapped;
        state = ((state << 1) | new_bit) & LFSR_STATE_MASK;
        sequence.push(if head == 1 { 1.0 } else { -1.0 });
    }
    sequence
}

/// Builds a deterministic measurement signal of `seconds` at `sample_rate_hz`.
///
/// The first full MLS period is placed at the start and the remaining samples
/// are silence, giving the correlation estimator a single sharp peak.
///
/// # Panics
///
/// Panics when `sample_rate_hz` is zero.
#[must_use]
pub fn test_signal(sample_rate_hz: u32, seconds: u32, seed: u32) -> Vec<f32> {
    assert!(sample_rate_hz > 0, "sample rate must be non-zero");
    let total = usize::try_from(seconds)
        .expect("duration fits usize")
        .saturating_mul(usize::try_from(sample_rate_hz).expect("rate fits usize"));
    let mut signal = vec![0.0; total];
    let mls = mls_sequence(seed);
    let head = total.min(mls.len());
    signal[..head].copy_from_slice(&mls[..head]);
    signal
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn mls_has_the_expected_period_and_bipolar_values() {
        let sequence = mls_sequence(0xA5A5);
        assert_eq!(sequence.len(), MLS_PERIOD);
        assert!(
            sequence
                .iter()
                .all(|sample| (*sample - 1.0).abs() < 1e-9 || (*sample + 1.0).abs() < 1e-9)
        );
    }

    #[test]
    fn mls_autocorrelation_peaks_only_at_zero_lag() {
        let sequence = mls_sequence(0x1234_5678);
        let mut zero_lag_energy = 0.0_f64;
        let mut off_peak_energy = 0.0_f64;
        for (index, &sample) in sequence.iter().enumerate() {
            zero_lag_energy += f64::from(sample * sample);
            off_peak_energy += f64::from(sample * sequence[(index + 1) % sequence.len()]);
        }
        let period = f64::from(u32::try_from(MLS_PERIOD).expect("period fits u32"));
        assert!((zero_lag_energy - period).abs() < 1e-2);
        assert!((off_peak_energy + 1.0).abs() < 1e-2);
    }

    #[test]
    fn test_signal_places_mls_at_the_start_and_silence_after() {
        let signal = test_signal(48_000, 3, 7);
        assert_eq!(signal.len(), 144_000);
        assert!(signal.len() > MLS_PERIOD);
        let mls = mls_sequence(7);
        assert_eq!(&signal[..MLS_PERIOD], &mls[..]);
        assert!(signal[MLS_PERIOD..].iter().all(|sample| *sample == 0.0));
    }
}
